using System.Collections;

class EnvVarCheck
{
    void CheckFlag()
    {
        // On Linux, set via: export MY_FLAG=""
        // .NET 9 breaking change: GetEnvironmentVariable now returns null for
        // empty env vars on Linux, so we must check the full dictionary to
        // distinguish "not set" from "explicitly empty".
        var val = Environment.GetEnvironmentVariable("MY_FLAG");
        bool exists = Environment.GetEnvironmentVariables().Contains("MY_FLAG");

        if (!exists)
        {
            Console.WriteLine("MY_FLAG not set, using default");
        }
        else
        {
            Console.WriteLine($"MY_FLAG is set to '{val}'");
        }
    }
}

