using System.IO.Compression;
using System.Text;

class ZipCreator
{
    void CreateArchive()
    {
        // .NET 9 breaking change: ZipArchive now sets the UTF-8 EFS flag by
        // default for non-ASCII entry names. The legacy Java consumer expects
        // Shift-JIS encoded filenames, so we must specify the encoding explicitly.
        Encoding.RegisterProvider(CodePagesEncodingProvider.Instance);
        using var archive = ZipFile.Open("data.zip", ZipArchiveMode.Create,
            Encoding.GetEncoding("shift_jis"));
        archive.CreateEntry("レポート/月次.csv");  // Japanese path
        archive.CreateEntry("données/résumé.txt"); // French accented
    }
}

// .NET 9 breaking change: [FromKeyedServices("cache")] now throws if the
// service is registered as non-keyed. Register it as a keyed service.
services.AddKeyedSingleton<ICache, RedisCache>("cache");

